<template>
  <view class="page-shell profile-page">
    <view class="profile-head">
      <button class="avatar-button" open-type="chooseAvatar" @chooseavatar="onChooseAvatar"><view class="avatar-ring"></view><image v-if="avatarPreview" :src="avatarPreview" mode="aspectFill"/><text v-else>{{(nickname||'你').slice(0,1)}}</text><view class="avatar-edit">✦</view></button>
      <view class="profile-copy"><input class="profile-name-input" v-model="nickname" type="nickname" maxlength="32" placeholder="请输入昵称"/><text>与你相伴的第 {{togetherDays}} 天</text></view>
      <button v-if="profileChanged" class="head-save" :loading="saving" @tap="saveProfile">保存</button>
    </view>

    <view class="stats-row"><view><text>{{stats.relationshipCount||0}}</text><text>联系人</text></view><view><text>{{stats.eventCount||'--'}}</text><text>重要日</text></view><view><text>{{stats.memoryCount||'--'}}</text><text>回忆</text></view></view>

    <view class="section-block">
      <text class="section-label">功能与数据</text>
      <view class="menu-list">
        <view class="menu-row" @tap="go('/pages/space/list')"><view class="menu-icon shared">家</view><view><text>家庭空间</text><text>与家人一起记录</text></view><text>›</text></view>
        <view class="menu-row" @tap="go('/pages/analytics/dashboard')"><view class="menu-icon data">数</view><view><text>数据概览</text><text>查看关系与记录分布</text></view><text>›</text></view>
        <view class="menu-row" @tap="go('/pages/ai/index')"><view class="menu-icon ai">✦</view><view><text>AI 助手</text><text>祝福、文案与礼物建议</text></view><text>›</text></view>
      </view>
    </view>

    <view class="section-block">
      <text class="section-label">支持</text>
      <view class="plain-list"><button open-type="feedback"><text>帮助与反馈</text><text>›</text></button><view @tap="about"><text>关于与你</text><text>›</text></view></view>
    </view>

    <button class="logout" @tap="logout">退出登录</button>
    <button class="delete-account" :loading="deletingAccount" :disabled="deletingAccount" @tap="deleteAccount">注销账号</button>
    <BottomNav v-if="store.isLogin" active="profile" />
  </view>
</template>

<script setup>
import{computed,ref}from'vue';import{onHide,onShow,onUnload}from'@dcloudio/uni-app';import BottomNav from '@/components/BottomNav.vue';import{store}from'@/store/index.js';import{userApi}from'@/api/user.js';import{memoryApi}from'@/api/memory.js';import{analyticsApi}from'@/api/analytics.js';import{spaceApi}from'@/api/space.js';
const user=ref(store.userInfo||{}),stats=ref({}),nickname=ref(store.userInfo?.nickname||''),avatarPreview=ref(store.userInfo?.avatar||''),selectedAvatar=ref(''),saving=ref(false),deletingAccount=ref(false);const togetherDays=computed(()=>{const date=new Date(user.value.createdAt||Date.now());return Math.max(1,Math.ceil((Date.now()-date.getTime())/86400000));});const profileChanged=computed(()=>nickname.value.trim()!==(user.value.nickname||'')||!!selectedAvatar.value);
let loadGeneration=0;const cancelPendingLoad=()=>{loadGeneration+=1;};onHide(cancelPendingLoad);onUnload(cancelPendingLoad);
onShow(async()=>{const generation=++loadGeneration;if(!store.isLogin){uni.reLaunch({url:'/pages/login/login'});return;}try{const[profile,profileStats,dashboard]=await Promise.all([userApi.getProfile(store.userId),userApi.getStats(store.userId),analyticsApi.dashboard(store.userId)]);if(generation!==loadGeneration)return;user.value=profile;stats.value={...(profileStats||{}),eventCount:dashboard?.overview?.totalEvents||0,memoryCount:dashboard?.overview?.totalMemories||0};nickname.value=profile.nickname||'';avatarPreview.value=profile.avatar||'';store.setUserInfo({...store.userInfo,...profile,accessToken:store.userInfo.accessToken});}catch{if(generation===loadGeneration)user.value=store.userInfo||{};}});
const onChooseAvatar=({detail})=>{selectedAvatar.value=detail.avatarUrl;avatarPreview.value=detail.avatarUrl;};const saveProfile=async()=>{const name=nickname.value.trim();if(!name)return uni.showToast({title:'请输入昵称',icon:'none'});saving.value=true;try{let avatar=user.value.avatar||'';if(selectedAvatar.value)avatar=(await memoryApi.uploadImage(selectedAvatar.value)).url;const updated=await userApi.updateProfile(store.userId,{nickname:name,...(avatar?{avatar}:{})});user.value=updated;selectedAvatar.value='';avatarPreview.value=updated.avatar||'';store.setUserInfo({...store.userInfo,...updated,accessToken:store.userInfo.accessToken});uni.showToast({title:'已保存',icon:'success'});}catch(error){uni.showToast({title:error?.message||'保存失败，请重试',icon:'none'});}finally{saving.value=false;}};
const go=url=>uni.navigateTo({url});const about=()=>uni.showModal({title:'与你',content:'版本 1.4.3\n记录重要的人和重要的日子',showCancel:false});const logout=()=>{store.logout();uni.reLaunch({url:'/pages/login/login'});};
const blockingSpaces=spaces=>(spaces||[]).filter(item=>['ACTIVE','PENDING'].includes(item.status)&&(item.createdById===store.userId||item.type==='PAIR'));
const blockerCopy=spaces=>{const names=spaces.slice(0,3).map(item=>`“${item.name}”`).join('、');const suffix=spaces.length>3?`等 ${spaces.length} 个空间`:'';return `${names}${suffix}需要先退出或解散，才能注销账号。`;};
const showSpaceBlockers=spaces=>uni.showModal({title:'请先处理共同空间',content:spaces.length?blockerCopy(spaces):'当前账号仍关联共同空间，请先退出或解散后再注销。',confirmText:'去处理',cancelText:'稍后',success:({confirm})=>{if(confirm)uni.navigateTo({url:'/pages/space/list'});}});
const deleteAccount=async()=>{if(deletingAccount.value)return;deletingAccount.value=true;try{const spaces=await spaceApi.list();const blockers=blockingSpaces(spaces);if(blockers.length)return showSpaceBlockers(blockers);const result=await uni.showModal({title:'注销账号',content:'注销后，你的联系人、私人回忆和日程将永久删除，且无法恢复。',confirmText:'确认注销',confirmColor:'#b64f43'});if(!result.confirm)return;await userApi.deleteAccount();logout();}catch(error){if(['ACCOUNT_HAS_OWNED_SPACES','ACCOUNT_HAS_ACTIVE_PAIR_SPACE'].includes(error?.errorCode)){const spaces=await spaceApi.list().catch(()=>[]);showSpaceBlockers(blockingSpaces(spaces));}else{uni.showToast({title:error?.message||'注销失败，请稍后重试',icon:'none'});}}finally{deletingAccount.value=false;}};
</script>

<style scoped>
.profile-page{padding-top:30rpx}.profile-head{display:flex;align-items:center}.avatar-button{position:relative;width:132rpx;height:132rpx;margin:0 22rpx 0 0;padding:0;overflow:visible;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#ead3c7;color:#684d42;font-size:40rpx;font-weight:700}.avatar-button image{width:100%;height:100%;border-radius:50%}.avatar-button view{position:absolute;right:-4rpx;bottom:0;width:46rpx;height:34rpx;border:3rpx solid #f7f7f5;border-radius:7rpx;background:#315c4d;color:#fff;line-height:31rpx;font-size:26rpx;font-weight:500}.profile-copy{flex:1;display:flex;flex-direction:column}.profile-copy text:first-child{font-size:36rpx;font-weight:750}.profile-copy text:last-child{margin-top:7rpx;color:#858c87;font-size:28rpx}.stats-row{min-height:144rpx;margin-top:26rpx;display:grid;grid-template-columns:repeat(3,1fr);border-top:1rpx solid #dfe2dd;border-bottom:1rpx solid #dfe2dd}.stats-row view{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center}.stats-row view:not(:last-child)::after{content:'';position:absolute;right:0;width:1rpx;height:48rpx;background:#dfe2dd}.stats-row text:first-child{font-size:34rpx;font-weight:750}.stats-row text:last-child{margin-top:3rpx;color:#8b918d;font-size:28rpx}.section-block{margin-top:30rpx}.section-label{display:block;margin-bottom:10rpx;color:#7f8681;font-size:28rpx}.profile-field{height:116rpx;padding:0 3rpx;display:flex;align-items:center;border-top:1rpx solid #dfe2dd;border-bottom:1rpx solid #dfe2dd;font-size:32rpx}.profile-field input{flex:1;height:96rpx;margin-left:24rpx;text-align:right;font-size:32rpx}.save-button{height:88rpx;margin-top:12rpx;border-radius:9rpx;background:#315c4d;color:#fff;line-height:88rpx;font-size:30rpx}.menu-list{border-top:1rpx solid #dfe2dd}.menu-row{min-height:128rpx;display:flex;align-items:center;border-bottom:1rpx solid #e2e5e0}.menu-icon{width:68rpx;height:68rpx;margin-right:16rpx;border-radius:8rpx;display:flex;align-items:center;justify-content:center;font-size:28rpx;font-weight:700;flex:none}.menu-icon.shared{background:#e4ece7;color:#315c4d}.menu-icon.data{background:#e1e6ec;color:#546777}.menu-icon.ai{background:#f1e6d2;color:#7b622e}.menu-row>view:nth-child(2){flex:1;display:flex;flex-direction:column}.menu-row>view:nth-child(2) text:first-child{font-size:32rpx;font-weight:650}.menu-row>view:nth-child(2) text:last-child{margin-top:4rpx;color:#8b918d;font-size:28rpx}.menu-row>text{color:#9ca29e;font-size:34rpx}.plain-list{border-top:1rpx solid #dfe2dd}.plain-list button,.plain-list>view{width:100%;height:112rpx;margin:0;padding:0 3rpx;display:flex;align-items:center;justify-content:space-between;border-bottom:1rpx solid #e2e5e0;background:transparent;color:#303833;font-size:32rpx;text-align:left}.plain-list button text:last-child,.plain-list>view text:last-child{color:#9ca29e;font-size:34rpx}.logout{height:92rpx;margin-top:32rpx;border:1rpx solid #d9ddd8;border-radius:9rpx;background:#fff;color:#555e58;line-height:90rpx;font-size:30rpx}.delete-account{width:100%;height:72rpx;margin:10rpx 0 0;padding:0;border:0;background:transparent;color:#ac5a50;font-size:26rpx;line-height:72rpx;text-align:center}
.profile-head{min-height:184rpx;padding:20rpx 20rpx 20rpx 16rpx;background:#fff;border:1rpx solid #dedfd9;border-radius:16rpx;box-shadow:0 10rpx 26rpx rgba(35,43,38,.05)}.avatar-button{width:152rpx;height:152rpx;padding:6rpx;border:0;box-shadow:0 0 0 6rpx #f3e7df,0 10rpx 20rpx rgba(93,71,61,.14)}.avatar-button image,.avatar-button>text{position:relative;z-index:1;width:100%;height:100%;border-radius:50%;display:flex;align-items:center;justify-content:center}.avatar-button image{object-fit:cover}.avatar-ring{position:absolute;inset:0;border:2rpx solid rgba(255,255,255,.85);border-radius:50%;z-index:2;pointer-events:none}.avatar-edit{position:absolute;z-index:3;right:-4rpx;bottom:0;width:44rpx;height:44rpx;border:4rpx solid #fff;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#315c4d;color:#fff;font-size:24rpx;line-height:36rpx}.profile-copy{min-width:0}.profile-name-input{width:100%;height:64rpx;padding:0;font-size:38rpx;line-height:64rpx;font-weight:750;color:#202522}.head-save{flex:none;height:64rpx;margin:0 0 0 12rpx;padding:0 18rpx;border-radius:9rpx;background:#315c4d;color:#fff;line-height:64rpx;font-size:28rpx}.profile-field,.save-button{display:none}
</style>
